window.MONSTER_CHUNK_12 = [{"name":"Jack-O'-Lantern","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"plant","init":-2,"senses":[{"type":"low-light vision"},{"type":"tremorsense","modifier":"30 ft."}],"auras":["fear (20 ft., DC 13)"],"ac":11,"ac_touch":8,"ac_flat_footed":11,"ac_mods":"-2 Dex, +3 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":-2,"will":12,"immunities":["plant traits"],"resists":[{"type":"fire","value":15}],"speed":[{"type":"land","speed":15}],"melee":"bite +3 (1d6+2), slam +3 (1d4+2 plus strangling entangle)","space":"5 ft.","reach":"5 ft. (10 ft. with slam)","special_attacks":[{"type":"breath weapon","details":"20-ft. cone, 1d10 fire, Reflex DC 12 half, usable every 1d4 rounds"},{"type":"explode"},{"type":"strangling ensnare","details":"DC 14"}],"strength":15,"dexterity":7,"constitution":12,"intelligence":2,"wisdom":14,"charisma":7,"baseatk":1,"cmb":34,"cmb_special":"+2 vs. sunder, +4 vs. bull rush","cmd":45,"cmd_special":"+2 vs. sunder, +4 vs. bull rush","feats":[{"feat":"Ability Focus (strangling ensnare)"}],"skills":[{"skill":"Perception","value":7}],"sq":[{"type":"pumpkin form"}],"environments":["any hills","any plains (pumpkin patches)","temperate forests"],"organizations":["solitary","patch (2-12)"],"treasure":"none","description_visual":"A carved pumpkin sits atop a writhing mass of thick ropey vines. Sinister flames dance within its leering, crudely carved face.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Explode","kind":"Ex","details":"One round after a jack-o'-lantern is reduced to 0 or fewer hit points, it explodes in a burst of flaming spores. Creatures within 10 ft. of an exploding jack-o'-lantern must succeed at a DC 12 Reflex save or take 2d6 points of fire damage and be stunned for 1 round. A successful save halves the damage and negates the stun. The save DC is Constitution-based."},{"type":"Fear Aura","kind":"Su","details":"Any creature within 30 ft. of a jack-o'- lantern must succeed at a DC 13 Will save or be shaken for 2d6 minutes. If the Will save is successful, the creature is immune to that jack-o'-lantern's fear aura for 24 hours. This is a vision-based mind-affecting fear effect. The save DC is Charisma-based and includes a +4 racial bonus."},{"type":"Pumpkin Form","kind":"Su","details":"A jack-o'-lantern can shrink in size and douse its sinister fiery radiance, allowing it to blend in almost perfectly with normal pumpkins and take 20 on its Stealth checks to hide in plain sight as a normal pumpkin. While using this ability, a jack-o'-lantern loses its fear aura. A jack-o'-lantern can use this ability as a full-round action and end it as a free action."},{"type":"Strangling Ensnare","kind":"Ex","details":"A jack-o'-lantern's slam attack entangles the target in its vines for 2d4 rounds unless the target succeeds at a DC 14 Reflex save. The target can attempt to burst these entangling vines before the duration expires with a successful DC 12 Strength check as a full-round action. While the target is entangled, its vines also grasp at the target's mouth. The target cannot speak or cast spells with verbal components while it is entangled by the jack-o'- lantern. When a creature is entangled by this ability, the jack-o'-lantern loses its slam attack, but it can end this ability as a free action. The save and the burst DCs are Constitution-based."}],"description":"Jack-o'-lanterns are semi-intelligent plant creatures spawned by fell magic and driven to burn and consume living flesh. Though they are mobile, jack-o'- lanterns prefer to remain in one spot until their food supplies run out. They typically lair within pumpkin patches, where they lie in wait and use their pumpkin form ability to ambush unsuspecting prey. Jack-o'-lanterns have been known to grow where the corpse of a powerful evil witch or wicked fey was buried, though this form of reproduction sometimes takes decades. Jack-o'-lanterns can also reproduce on their own. Immediately after killing and devouring an intelligent being, a jack-o'-lantern excretes its victim's remains as a smoldering, paste-like slurry that quickly sinks into the ground. One day later, 1d3 fully mature-and ravenous-jack-o'- lanterns emerge from the tainted soil.","ecology":"","habitat_society":""},{"name":"Jigsaw Shark","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","subtypes":["aquatic"],"init":6,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"keen scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":5,"will":1,"speed":[{"type":"swim","speed":60}],"melee":"bite +3 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":14,"constitution":13,"intelligence":1,"wisdom":12,"charisma":2,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":6},{"skill":"Swim","value":10}],"environments":["any oceans"],"organizations":["solitary","pair","school (3-6)"],"treasure":"none","description_visual":"Jagged markings decorate the body of this human-sized shark. A multitude of stains on its large teeth tell of the frequency and ferocity with which it uses its bite.","group":"Shark","source":"AP 57","description":"The fact that these sharks dwell in shallow coastal waters places them in direct contact with those making a living from the sea. It's not uncommon to hear stories of jigsaw sharks leaping from the water and taking out dockworkers or fishermen in small boats. Their patchwork coloration of browns and blue-grays partly inspires their name.","ecology":"","habitat_society":""},{"name":"Jinkin","cr":1,"xp":400,"alignment":"CE","size":"Tiny","type":"fey","init":4,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+4 Dex, +1 dodge, +1 natural, +2 size","hp":6,"hd":"1d6+3","hdvalue":1,"fort":0,"ref":6,"will":4,"dr":"5/cold iron","sr":12,"speed":[{"type":"land","speed":40}],"melee":"short sword +6 (1d3-4/19-20), bite +1 (1d2-4)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"},{"type":"tinker"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"prestidigitation"}]},{"frequency":"1/hour","spells":[{"spell":"dimension door","details":"self plus 5 lbs. only"}]}],"strength":3,"dexterity":19,"constitution":11,"intelligence":14,"wisdom":14,"charisma":15,"baseatk":0,"cmb":2,"cmd":9,"feats":[{"feat":"Dodge"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Craft (traps)","value":10},{"skill":"Disable Device","value":9},{"skill":"Escape Artist","value":8},{"skill":"Perception","value":6},{"skill":"Sleight of Hand","value":8},{"skill":"Stealth","value":16},{"skill":"Use Magic Device","value":6}],"languages":["Undercommon"],"environments":["any underground","any urban"],"organizations":["solitary","pair","mob (3-12)","infestation (13-20 with 1-3 sorcerers of 1st-3rd level, 1 rogue leader of 2nd-4th level, 2-8 trained stirges, 2-5 trained darkmantles, and 1-2 trained dire bats)"],"treasure":"standard (short sword)","description_visual":"Grimacing like a maniac, this lean little bat-eared horror displays a mouth full of needle-like teeth and glowing, orange eyes.","group":"Gremlin","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Tinker","kind":"Sp","details":"A group of six jinkins working together over the course of an hour can create an effect identical to bestow curse on any living creature. This effect functions at CL 6th and has a range of 60 ft., and the target creature must be either willing or helpless (but still gets a saving throw to resist). The save is DC 14 + the Charisma modifier of the jinkin with the highest Charisma score (DC 16 for most groups of jinkins). Alternatively, the group of jinkins can attempt to infuse a magic item with a curse. The nature of this curse is determined randomly; half of these curses make the magic item unreliable (each time the item is used, there is a 20% chance it doesn't function), while the other half give the item a random requirement. A jinkin can take part in a tinkering only once per day, and may only tinker with a creature or object that isn't already cursed. Once a tinkering curse is in place, it is permanent until removed via an effect like remove curse. All jinkin tinkerings function as a curse created by a 6th-level caster."}],"description":"Sneaky and sadistic, jinkins are hideous gremlins that inhabit the dark places underground. Well acclimated to the shadows, they hide in cramped quarters and attack larger creatures when they're strategically positioned. Jinkins commonly work with or near larger or more powerful creatures; these larger creatures provide cover for the jinkins' trickery. They use dimension door to exit any battle that goes badly, taking any stolen goods with them.\n\nJinkins delight in leading larger creatures into dangerous caves or pits, usually by lunging out of the shadows to make a single sneak attack against a creature and then running away, taking care while \"fleeing\" to remain visible to their target so that they can lure the victim into a trap.\n\nJinkins also hold dangerous grudges, and one might follow a creature that supposedly slighted it for weeks, looking for an opportunity to take revenge. This revenge can take many forms, from leading horses astray to contaminating food supplies to directing larger monsters toward the begrudged creature.\n\nOne of the most direct and unwelcome revenges of the jinkins is the destruction or cursing of magical items. Many times they'll observe camped enemies from a distance and either steal an item to tinker with it or just use their tinkering magic at a distance to annoy the item's owner. Once a jinkin has worked its sabotage on a stolen item, the jinkin either grows bored with the item or may attempt to return it to its owner. Jinkin lairs are often cluttered with stolen items that bear curses the jinkins themselves have forgotten all about.\n\nDwarves in particular hate jinkins, with numerous tales in their folklore telling of tragedy at the hands of the gremlins. The loathing is largely mutual.\n\nThe average jinkin stands almost 2 ft. tall and weighs about 13 pounds.","ecology":"","habitat_society":""},{"name":"Krenshar","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"magical beast","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":13,"hd":"2d10+2","hdvalue":2,"fort":4,"ref":5,"will":1,"speed":[{"type":"land","speed":40}],"melee":"bite +2 (1d6), 2 claws +2 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"skullface"}],"strength":11,"dexterity":14,"constitution":13,"intelligence":6,"wisdom":12,"charisma":13,"baseatk":2,"cmb":2,"cmd":14,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Intimidate","value":1,"special":"+5 to demoralize"},{"skill":"Perception","value":5},{"skill":"Stealth","value":10}],"languages":["Sylvan (can't speak)"],"environments":["temperate forests","temperate plains"],"organizations":["solitary","pair","pride (6-10)"],"treasure":"none","description_visual":"This earless, panther-like beast snarls as the skin of its face twitches, then peels back to reveal the bone and flesh beneath.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Skullface","kind":"Su","details":"As a standard action, a krenshar can pull the skin back from its face, revealing the musculature and bony structures of its skull. This counts as using Intimidate to demoralize an opponent, and is an extraordinary ability. The krenshar can emit a loud screech while peeling back its skin, causing potent fear in a single creature within 100 ft. that can see the krenshar. The targeted creature must make a DC 12 Will save or become frightened (if the target has 6 or fewer Hit Dice) or shaken (if the target has more than 6 Hit Dice) for 1d4 rounds. A creature that successfully saves cannot be affected again by the same krenshar's skullface ability for 24 hours. This is a sonic, mind-affecting fear effect. The save DC is Charisma-based."}],"description":"The krenshar is a strange creature that resembles a large but earless hunting cat, save that it can retract the fur and skin on its face to reveal the glistening skull and musculature underneath. Combined with its strange, keening wail, this horrifying display is enough to paralyze prey and send formidable opponents running.\n\nKrenshar's retractable skin allows it to dine on carrion with a lower risk of picking up disease-carrying vermin, much like a vulture's bare head and neck. When the creature finishes eating, restoring the facial skin to its normal position scrapes off gore and clinging bugs. The ability to retract their skin is demonstrated in other contexts as well-male krenshars bare their skulls at rivals as a challenge over mates, females use this ability to ward off undesired suitors, and hunting adults use it to scare prey into ambushes.\n\nThough krenshars generally prefer to stalk herd animals like deer or cattle, they have no qualms about taking on humanoids when food is scarce. They average 4 to 5 ft. in length and weigh approximately 175 pounds.\n\nScholars have long debated the confusing nature of krenshar intelligence. While clearly more intelligent than mere animals, the creatures seem to lack all but the most rudimentary language of snarls and yowls, and aside from the scare tactics that make them notorious, tend to behave much like mundane cats or wolves, even going so far as to occasionally be befriended by rangers or druids. Those who deny krenshars' intelligence, however, need only look into their strange violet eyes or observe the ease with which they manipulate and outmaneuver their prey to realize their folly-an error few make twice.","ecology":"","habitat_society":""},{"name":"Lacedon","cr":1,"xp":400,"alignment":"CE","size":"Medium","type":"undead","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":2,"ref":2,"will":5,"defensive_abilities":["channel resistance +2"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"bite +3 (1d6+1 plus disease and paralysis) and 2 claws +3 (1d6+1 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"paralysis","details":"1d4+1 rounds, DC 13, elves are immune to this effect"}],"strength":13,"dexterity":15,"intelligence":13,"wisdom":14,"charisma":14,"baseatk":1,"cmb":2,"cmd":14,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Climb","value":6},{"skill":"Perception","value":7},{"skill":"Stealth","value":7},{"skill":"Swim","value":6}],"languages":["Common"],"environments":["any land"],"organizations":["solitary","gang (2-4)","wing (7-12)"],"treasure":"standard","description_visual":"This humanoid creature has long, sharp teeth, and its pallid flesh is stretched tightly over its starved frame.","group":"Ghoul","source":"PFRPG Bestiary","special_abilities":[{"type":"Disease","kind":"Su","details":"Ghoul Fever: Bite-injury; save Fort DC 13; onset 1 day; frequency 1 day; effect 1d3 Con and 1d3 Dex damage; cure 2 consecutive saves. The save DC is Charisma-based."}],"description":"A humanoid who dies of ghoul fever rises as a ghoul at the next midnight. A humanoid who becomes a ghoul in this way retains none of the abilities it possessed in life. It isn't under the control of any other ghouls, but it hungers for the flesh of the living and behaves like a normal ghoul in all respects. A humanoid of 4 Hit Dice or more rises as a ghast.","ecology":"","habitat_society":""},{"name":"Leaf Ray","cr":1,"xp":400,"alignment":"N","size":"Small","type":"plant","init":3,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size","hp":15,"hd":"2d8+6","hdvalue":2,"fort":6,"ref":3,"will":1,"immunities":["plant traits"],"speed":[{"type":"land","speed":5},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"stinger +3 (1d4+1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"seed"}],"strength":12,"dexterity":16,"constitution":17,"intelligence":1,"wisdom":13,"charisma":4,"baseatk":1,"cmb":1,"cmd":14,"cmd_special":"can't be tripped","feats":[{"feat":"Flyby Attack"}],"skills":[{"skill":"Fly","value":9},{"skill":"Perception","value":5}],"environments":["temperate forests","warm forests"],"organizations":["solitary","rustle (2-20)"],"treasure":"none","description_visual":"This creature looks like a broad leaf with whiskers like a catfish and a dangerous stinger trailing behind it.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 14; frequency 1/round for 6 rounds; effect 1d2 Dex; cure 1 save."},{"type":"Seed","kind":"Ex","details":"Once per day, a leaf ray can implant a seed into a helpless target with its stinger. As a full-round action, the leaf ray stings its victim, depositing a seed into the victim's flesh. This process deals 1 hit point of damage to the victim, but the implanted creature isn't subject to the leaf ray's poison in this process. The seed germinates inside the victim, making it sickened while it harbors the leaf ray seed, and dealing 1d2 points of Constitution damage to the victim each day the seed grows within. This damage is negated with a successful DC 14 Fortitude save. The seed feeds off the victim's body and only grows into a new leaf ray tree when the victim dies from Constitution damage. Removing an implanted seed requires a successful DC 20 Heal check (a full-round action); each attempt deals 1 hit point of damage. Although immunity to disease offers no special protection against a leaf ray seed's implantation, remove disease, heal, or similar effects automatically destroy any implanted seeds."}],"description":"Growing in the upper canopies of massive trees, leaf rays fly through the air in search of food. Barely sentient, leaf rays have just enough intelligence to find nourishment and pick out creatures suitable for harboring their seeds. These creatures are hardly picky in their quest for either, merely requiring a warm-blooded living creature, preferably mammalian, for each purpose. Leaf rays begin their lives as buds in the tops of deciduous trees, and form a symbiotic relationship with these trees, often leaving the husks of their victims under their host trees to decay and fertilize the soil. During its budding stage, a leaf ray spends its time flexing its body in reaction to blowing winds in order to prepare itself for flight. Once a leaf ray has matured, it can separate its stingerlike stem from the parent tree and soar through the air. A leaf ray measures 3 ft. across and weighs only 2 pounds.\n\nVARIANT LEAF RAYS Leaf rays change color in depending on the season, but they don't die off during winter. The stats above represent a leaf ray in the spring and summer. The following variations follow the changing seasons.\n\nFall: A leaf ray turns shades of yellow and red in the fall, and its poison's purpose shifts to deal Strength damage instead of Dexterity damage.\n\nWinter: A leaf ray in the winter turns a dull range of browns and grays, and its poison deals Constitution damage instead of Dexterity damage. Because of this, few leaf rays are successful in implanting their seeds during this season.","ecology":"","habitat_society":""},{"name":"Lemure","cr":1,"xp":400,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 natural","hp":13,"hd":"2d10+2","hdvalue":2,"fort":4,"ref":3,"will":0,"dr":"5/good or silver","immunities":["fire","mind-affecting effects","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"speed":[{"type":"land","speed":20}],"melee":"2 claws +2 (1d4)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":10,"constitution":12,"wisdom":11,"charisma":5,"baseatk":2,"cmb":2,"cmd":12,"environments":["any (Hell)"],"organizations":["solitary","pair","gang (3-5)","swarm (6-17)","mob (10-40 or more)"],"treasure":"none","description_visual":"A roiling wave of f lesh gushes forward. Amid the fatty surge wriggle half-formed limbs and a dripping tumorous face.","group":"Devil","source":"PFRPG Bestiary","description":"The least of devilkind, lemures roil forth from the ranks of souls damned to Hell, shapeless masses of quivering flesh. What spark of instinct or memory lingers on within a lemure's semi-consciousness regularly shapes its features to mimic those of its tormentors or the tortured souls around it. Grotesque and useless, a lemure's features speak nothing of what it once was. Many exhibit multiple terrible visages or are nothing more than churning pillars of cancerous flesh. Only their knobby, flailing limbs work as they should, and those they merely use to destroy any non-infernal life that draws too near. Moving lemures typically congeal in forms over 4 ft. tall and weigh upward of 200 pounds, though when at rest these disgusting fiends often appear to be little more than lumps of melted flesh and malformed features. Although among the most loathsome creatures in existence, lemures serve a vital role in Hell's perverse ecology. When at the end of a mortal life a creature's soul is damned-whether because it revered diabolical forces or failed in the worship of another deity-it joins the masses of suffering souls filling the plains of Avernus, Hell's first layer. Here a soul's torments begin as lesser devils marshal it along with similar spirits in preparation for a long, perilous journey to one of Hell's deeper layers-typically one suited to the punishments appropriate to the soul's crimes, or merely the domain of a devil who has need for slaves. Upon reaching the realm of their damnation, souls face untold lifetimes of torment at the hands of devils, other fiendish beings, and the deadly machinations of Hell itself. As the formerly mortal essences slowly go mad, they forget their lives, grow bestial, and eventually become little more than automatons of fear and hatred. After ages of such existence, the cruel processes of Hell either utterly annihilate the soul or-in the cases of the most profane spirits-reconsecrate such forsaken beings into lemures, the building blocks of devils, unthinking waves of filth and diabolical flesh. Such repulsive beings assemble in vast mobs, waves of putrescence thousands upon thousands strong. Greater devils can spot the most corrupt of these fiends and, either through mysterious tortures or the powers of Hell itself, reshape them into true devils, newly born and ready to obediently serve in the legions of the damned.","ecology":"","habitat_society":""},{"name":"Lizardfolk","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"humanoid","subtypes":["reptilian"],"init":0,"ac":17,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+5 natural, +2 shield","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":0,"will":0,"speed":[{"type":"land","speed":30},{"type":"swim","speed":15}],"melee":"morningstar +2 (1d8+1), claw  +0 (1d4), bite +0 (1d4)","ranged":"javelin +1 (1d6+1)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":10,"constitution":13,"intelligence":9,"wisdom":10,"charisma":10,"baseatk":1,"cmb":2,"cmd":12,"feats":[{"feat":"Multiattack"}],"skills":[{"skill":"Acrobatics","value":2},{"skill":"Perception","value":1},{"skill":"Swim","value":10}],"languages":["Draconic"],"sq":[{"type":"hold breath"}],"environments":["temperate swamps"],"organizations":["solitary","pair","band (3-12)","tribe (13-60)"],"treasure":"none","description_visual":"This reptilian humanoid has green scales, a short and toothy snout, and a thick alligator-like tail.","source":"PFRPG Bestiary","special_abilities":[{"type":"Hold Breath","kind":"Ex","details":"A lizardfolk can hold its breath for a number of rounds equal to 4 times its Constitution score before it risks drowning."}],"description":"Lizardfolk are proud and powerful reptilian predators that make their communal homes in scattered villages deep within swamps and marshes. Uninterested in colonization of the dry lands and content with the simple weapons and rituals that have served them well for millennia, lizardfolk are viewed by many other races as backwater savages, but within their isolated communities lizardfolk are actually a vibrant people filled with tradition and an oral history stretching back to before humans walked upright.\n\nMost lizardfolk stand 6 to 7 ft. tall and weigh 200 to 250 pounds, their powerful muscles covered in scales of gray, green, or brown. Some breeds have short dorsal spikes or brightly colored frills, and all swim well by moving with flicks of their powerful 4-foot-long tails. While completely at home in the water, they breathe air and return to their clustered mound-dwellings to breed and sleep. As their reptilian blood makes them sluggish in the cold, most lizardfolk hunt and work during the day and retreat to their homes at night to curl up with other tribesmen in the shared warmth of large peat fires.\n\nThough generally neutral, lizardfolks' standoffish demeanor, staunch rejection of civilization's \"gifts,\" and legendary ferocity in battle cause them to be viewed negatively by most humanoids. These traits stem from good reasons, however, as their own slow rate of reproduction is no match for warm-blooded humanoids, and those tribes who don't defend their wetland territories to the last breath quickly find themselves overwhelmed by the mammalian hordes. As for their tendency to consume the bodies of dead friends and enemies alike, the practical lizardfolk are quick to point out that life is hard in the swamp, and nothing should go to waste.\n\nThe lizardfolk presented here dwell in a swampy environment. Lizardfolk tribes can exist in other environments as well, but they lose their swim speed and instead gain a climb speed of 15 ft.","ecology":"","habitat_society":"","gear":"heavy wooden shield, morningstar, 3  javelins"},{"name":"Manta Ray","cr":1,"xp":400,"alignment":"N","size":"Large","type":"animal","subtypes":["aquatic"],"init":1,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+1 Dex, +3 natural, -1 size","hp":19,"hd":"3d8+6","hdvalue":3,"fort":5,"ref":4,"will":2,"speed":[{"type":"swim","speed":60}],"melee":"tail slap +4 (1d6+4)","space":"10 ft.","reach":"10 ft.","strength":16,"dexterity":13,"constitution":15,"intelligence":1,"wisdom":13,"charisma":2,"baseatk":2,"cmb":6,"cmd":17,"feats":[{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":6},{"skill":"Swim","value":15}],"environments":["warm oceans"],"organizations":["solitary","pair","flight (3-12)"],"treasure":"none","description_visual":"Gliding gracefully through the water on wing-like fins, this large ray scoops up tiny morsels in its wide mouth.","group":"Ray","source":"PFRPG Bestiary 2","description":"These fish are nonaggressive and generally avoid contact with other creatures. They filter plankton and similar small organisms from the water through their gaping, toothless maws.\n\nManta Ray Companion Starting Statistics: Size Medium; Speed swim 60 ft.; AC +1 natural; Attack tail slap (1d4); Ability Scores Str 8, Dex 15, Con 11, Int 1, Wis 13, Cha 2; Special Qualities low-light vision.\n\n4th-Level Advancement: Size: Large; AC +2 natural armor; Attack tail slap (1d6); Ability Scores Str +8, Dex -2, Con +4; Special Qualities blindsense 30 ft.","ecology":"","habitat_society":""},{"name":"Melancholic Ooze Swarm","cr":1,"xp":400,"alignment":"N","size":"Tiny","type":"ooze","subtypes":["swarm"],"init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":7,"ac_touch":7,"ac_flat_footed":7,"ac_mods":"-5 Dex, +2 size","hp":17,"hd":"2d8+8","hdvalue":2,"fort":4,"ref":-5,"will":-5,"immunities":["ooze traits","swarm traits"],"resists":[{"type":"electricity","value":5}],"weaknesses":["vulnerability to acid"],"speed":[{"type":"land","speed":10}],"melee":"swarm (1 plus viscous)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 15"},{"type":"paralyzing slime"},{"type":"viscous","details":"DC 15"}],"strength":14,"dexterity":1,"constitution":18,"wisdom":1,"charisma":1,"baseatk":1,"cmb":-6,"cmd":6,"cmd_special":"can't be tripped","environments":["any underground"],"organizations":["solitary","pair","glob (3-4)"],"treasure":"none","description_visual":"Dozens of tiny globs of slime move on their own, acting as one being, alternately clinging to each other and separating in a riot of oozing momentum.","group":"Ooze","source":"AP 43","special_abilities":[{"type":"Paralyzing Slime","kind":"Ex","details":"Melancholic oozes are composed of chemical depressants. Any living creature that begins its turn affected by the swarm's viscous ability must make a DC 15 Fortitude save or be paralyzed for 1 round. This is a mindaffecting effect. Creatures immune to poison are immune to this effect."},{"type":"Viscous","kind":"Ex","details":"As described in the sanguine ooze swarm's special abilities, except that the Reflex save DC is 15 and the patches are destroyed if the victim takes any amount of acid damage."}],"description":"Formed from accumulations of runoff from arcane laboratories and regions of magical calamity, alchemical oozes are fist-sized blobs of volatile chemicals. Although composed of unpredictable compounds and toxins, these mobile oozes pose little threat individually, but in polluted quagmires and tainted sewers can collect in numbers great enough to threaten creatures many times their size. Swarms of the slimes linger in such contaminated areas and seek new accretions of vital solutions, like those found within the bodies of higher life forms, to fuel their erratic life cycles. Found in numerous varieties with a host of differing abilities, these weird, clinging oozes have been differentiated by likening them to the humors said to compose the bodies of living beings. Appearing at first to be a collection of tiny blobs of viscous, translucent fluid, alchemical oozes become far more terrifying once their hungry nature becomes apparent. Each swarm is composed of several hundred palm-sized balls of ooze that all scuttle along as a single unit.","ecology":"","habitat_society":""},{"name":"Mockingfey","cr":1,"xp":400,"alignment":"CN","size":"Tiny","type":"fey","init":3,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 size","hp":13,"hd":"3d6+3","hdvalue":3,"fort":2,"ref":6,"will":4,"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 talons +6 (1d2-2)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"daze"}]}],"strength":6,"dexterity":16,"constitution":13,"intelligence":7,"wisdom":12,"charisma":13,"baseatk":1,"cmb":2,"cmd":10,"feats":[{"feat":"Flyby Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Disguise","value":7},{"skill":"Fly","value":15},{"skill":"Perception","value":7},{"skill":"Stealth","value":16}],"sq":[{"type":"mock"}],"environments":["any forests (First World)"],"organizations":["solitary","pair","jape (3-20)"],"treasure":"standard","description_visual":"This tiny sprite has the head of a humanoid and the body of a brilliantly colored parrot.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Mock","kind":"Su","details":"As a standard action, a mockingfey can magically take on the appearance of any creature it can see. This functions like disguise self, but with no restrictions on duration, creature type, or size. The mockingfey doesn't change size, and if the creature it's mimicking is larger than it, the mockingfey simply appears to be a miniature version. Anyone interacting with this effect can attempt a DC 12 Will save to see through the ruse. A mockingfey can maintain a given form indefinitely, but cannot change to any form other than its own without visual reference-once a given disguise has ended, the fey must see the subject again to resume that form. The save DC is Charisma-based."}],"description":"Mockingfey originally stem from the First World, where they're regarded as entertainment by locals and nuisances by visitors, who are the usual butt of the creatures' pranks. The pint-sized fey often congregate in large colonies called japes or mockingdells, inhabiting the trees near a commonly traversed path or meadow. When an intelligent creature enters the grove, one of the bird-sprites flies down to perch on the traveler's shoulder or some nearby vantage. It then promptly shifts shape to become a perfect, miniature doppelganger of the creature in question, proceeding to cavort and imitate the newcomer in a most convincing and unf lattering manner, mimicking the creature's tone but chattering only gibberish.\n\nThis gibberish isn't solely for comic effect, as while mockingfey are eager (if distractible) students in most matters, they refuse to use verbal language of any sort, believing that words unnecessarily constrain the things they describe. Instead, they communicate through gestures, pantomime, and elaborate dances. Those who think them mere beasts, however, are quickly set straight, as enemies of mockingfey are confronted with disorienting magic and the mockingfey's capricious allies from the First World.\n\nWhile many people find mockingfeys' antics irritating, the little creatures are surprisingly useful allies, with a loyal, friendly nature toward those who treat them well, and an insatiable curiosity that makes them surprisingly well informed about their surroundings. This same curiosity extends to things most folks would leave alone, such as the portal-like breach scars between the Material Plane and the First World. When such planar rifts occur, mockingfey are often some of the first creatures through, with colonies found in Kyonin, the River Kingdoms, and sylvan groves around the Inner Sea. Those illusionists and other spellcasters who seek such puckish familiars (and take the Improved Familiar feat) often find them worth the resulting hassle-if just barely. A typical mockingfey is 8 inches tall and weighs 2 pounds.","ecology":"","habitat_society":""},{"name":"Monaciello","cr":1,"xp":400,"alignment":"CE","size":"Small","type":"fey","init":2,"senses":[{"type":"low-light vision"}],"auras":["stymie channeling (20 ft.; DC 12)"],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":14,"hd":"2d6+7","hdvalue":2,"fort":2,"ref":5,"will":4,"save_mods":"+4 vs. divine magic","dr":"5/cold iron","sr":12,"speed":[{"type":"land","speed":30}],"melee":"bite +4 (1d4-2), dagger +4 (1d3-2/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"ghost sound"},{"spell":"prestidigitation"},{"spell":"putrefy food and drink"},{"spell":"silent image"}]},{"frequency":"1/day","spells":[{"spell":"glitterdust"}]}],"strength":6,"dexterity":15,"constitution":14,"intelligence":11,"wisdom":12,"charisma":13,"baseatk":1,"cmb":-2,"cmd":10,"feats":[{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Disable Device","value":8},{"skill":"Escape Artist","value":7},{"skill":"Perception","value":6},{"skill":"Sense Motive","value":6},{"skill":"Stealth","value":18,"special":"+14 when moving"}],"languages":["Aklo"],"sq":[{"type":"compression"},{"type":"magic bag"}],"environments":["any urban"],"organizations":["solitary","pair","congregation (3-12)","infestation (13-20 plus 1-3 sorcerers of 1st-3rd level, 1 rogue leader of 2nd-4th level, 2-14 trained dire rats, 2-5 trained venomous snakes, and 1-3 rat swarms)"],"treasure":"double (always gold coins)","description_visual":"Dressed in red robes like those of a monk, this little monster displays a sharp-toothed smile and flips a gold coin in its hand.","group":"Gremlin","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Magic Bag","kind":"Su","details":"A monaciello always carries its pouch with it. This pouch contains an extradimensional space and operates like a bag of holding (type I). If this pouch is separated from the monaciello, all of its former contents are lost, and it becomes a normal bag that contains a number of coins equal to double the treasure value of a creature of the gremlin's CR. A monaciello that loses its pouch must create a new one, a process that takes 1d4 days. Until the new pouch is finished, it remains a non-magical bag, only becoming a fully functional extradimensional space once completed."},{"type":"Stymie Channeling","kind":"Su","details":"A monaciello gremlin is surrounded by an aura of blasphemy. Any creatures channeling energy within 20 ft. of a monaciello must succeed at a DC 12 Will save or be unable to channel for that round. The use isn't lost, but the action is wasted."}],"description":"Most often found in urban environments, this gremlin lives among humanity, taunting religious and scholarly organizations with its pranks. Monaciello gremlins are most commonly found in monasteries and cathedrals where they wriggle their way up from the sewers and catacombs to play tricks on the devout. These tricksters pull blankets off sleeping clergy members, harass servants, spoil food, and hide valuables from their owners. Enamored with gold, they often overinf late the value of things with illusions, and even throw handfuls of gold coins (or illusions of gold coins if they are feeling especially stingy) to distract creatures on their trail. They pull these coins from their ever-present magical bags, confident they can always pilfer more. A monaciello stands 2-1/2 ft. tall and weighs approximately 20 pounds.","ecology":"","habitat_society":""},{"name":"Mongrelman","cr":1,"xp":600,"alignment":"LN","size":"Medium","type":"monstrous humanoid","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 natural","hp":15,"hd":"2d10+4","hdvalue":2,"fort":2,"ref":4,"will":4,"speed":[{"type":"land","speed":30}],"melee":"club +4 (1d6+3) or  slam +4 (1d4+3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":13,"constitution":15,"intelligence":10,"wisdom":12,"charisma":7,"baseatk":2,"cmb":4,"cmd":15,"feats":[{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":6},{"skill":"Perception","value":6},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":13},{"skill":"Survival","value":5}],"languages":["Common","Undercommon"],"sq":[{"type":"sound mimicry","details":"voices"}],"environments":["any ruins","any underground"],"organizations":["solitary","pair","gang (3-6)","band (7-12)","tribe (21-30 plus 30% noncombatants, 2-4 rogues of 1st-3rd level, 1-2 oracles or witches of 2nd-4th level, 1 fighter or ranger chieftain of 3rd-6th level, 4-6 dire bats, and 3-20 dire rats)"],"treasure":"standard (club)","description_visual":"Ivory tusks, insect chitin, matted fur, scaly flesh, and more combine to form a hideous humanoid shape.","source":"PFRPG Bestiary 2","description":"Despite their monstrous appearances, mongrelmen are generally hardworking and peaceful creatures. A mongrelman can produce offspring with any humanoid, mixing bloodlines in strange ways to create hardier crossbreeds. No two mongrelmen look the same. One may have a face that is half hobgoblin, half lizardfolk, with one human-like foot and one cloven hoof, while his sister may have elven ears, a dwarven beard, orc tusks, and clawed hands. Each mongrelman usually has characteristics from at least a half-dozen different races.\n\nThis strange mixture enforces mongrelmen's place in the edges of the world, for they are shunned by all who fear their twisted appearance. Mistaken as enemies by all, mongrelmen prefer to be left alone.\n\nMost mongrelmen live below the surface of the world in hidden caves far from civilization. These creatures pride themselves on their survival skills, for the bowels of the earth are no place for weaklings.\n\nOther foul and intelligent races who claim dominion in the underworld take mongrelmen as slaves (particularly morlocks), finding this deformed race's docile nature and hardworking attitude makes them extremely useful as tools of labor. In this role, mongrelmen still fall back on their pride of survival, slow to rebel and patiently waiting for the overthrow of their masters.\n\nMongrelmen dwelling on the surface sometimes live amid the hustle and bustle of cities, sequestering themselves in ghettos and sewers to avoid notice. Urban mongrelmen may rely on begging and pickpocketing to get by, but most form rural communities near trading routes.\n\nDespite their varied physical forms, most mongrelmen average 5-6 ft. tall and weigh between 150 and 250 pounds on average. A tragically short lifespan limits the creatures' population growth-mongrelmen rarely live past 35 years.","ecology":"","habitat_society":""},{"name":"Mythic Human Skeleton","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"undead","subtypes":["mythic"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 Dex, +3 natural","hp":17,"hd":"2d8+8","hdvalue":2,"fort":0,"ref":2,"will":3,"defensive_abilities":["channel resistance +2"],"dr":"5/bludgeoning","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"2 scimitars +3 (1d6+2/18-20)  or 2 claws +3 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"mythic power","details":"1/day, surge +1d6"},{"type":"relentless"},{"type":"superior two-weapon fighting"}],"strength":15,"dexterity":14,"wisdom":10,"charisma":10,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Improved Initiative","type":"bonus"},{"feat":"Improved Initiative","type":"mythic"}],"environments":["any"],"organizations":["any"],"treasure":"standard (2 scimitars)","description_visual":"Its eyes glowing like bluish-white flames amid the shadows of its kingly helm, this skeleton wields two fearsome scimitars.","group":"Skeleton","source":"Mythic Adventures","description":"A mythic skeleton is an animated corpse created with mythic magic such as mythic animate dead. It has an unnatural cunning that belies its mindless nature and a natural instinct for killing.","ecology":"","habitat_society":""},{"name":"Ningyo","cr":1,"xp":400,"alignment":"NE","size":"Small","type":"monstrous humanoid","subtypes":["aquatic"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+1 Dex, +1 natural, +1 size","hp":13,"hd":"2d10+2","hdvalue":2,"fort":1,"ref":4,"will":5,"defensive_abilities":["poison flesh"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":40}],"melee":"2 claws +2 (1d3-1), bite +2 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"group grappler"},{"type":"startle"},{"type":"swarming"}],"strength":8,"dexterity":13,"constitution":12,"intelligence":6,"wisdom":15,"charisma":11,"baseatk":2,"cmb":2,"cmd":11,"cmd_special":"can't be tripped","feats":[{"feat":"Step Up"}],"skills":[{"skill":"Stealth","value":10},{"skill":"Swim","value":12}],"languages":["Aquan"],"sq":[{"type":"amphibious"},{"type":"nocturnal undeath"}],"environments":["warm oceans"],"organizations":["solitary","pair","shoal (3-22)"],"treasure":"standard","description_visual":"This dog-sized creature combines the upper half of a deformed monkey with the lower half of a thrashing fish.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Group Grappler","kind":"Ex","details":"A ningyo has a +2 racial bonus on combat maneuver checks. When two or more ningyos are grappling the same creature, each gains a +1 bonus on grapple combat maneuver checks and a +1 bonus on grapple damage rolls."},{"type":"Nocturnal Undeath","kind":"Su","details":"The body of a ningyo never rests peacefully. Every night, an hour after sundown, an intact ningyo corpse animates; its type changes to undead (aquatic), and it gains undead immunities, bonus hit points based on its Charisma instead of Constitution, and the startle ability. At dawn, the undead ningyo becomes a corpse again. An undead ningyo knows when the dawn is coming and attempts to find shelter so it isn't discovered as a corpse. A ningyo missing a limb, head, or tail doesn't animate at night, but can do so if reunited with its missing body part. A ningyo corpse that is burned or torn apart and its pieces scattered doesn't rise as an undead."},{"type":"Poison Flesh","kind":"Ex","details":"Any creature that bites a ningyo or swallows any part of it becomes poisoned. Ningyo Flesh: Ingested; save Fort DC 12; onset 1 minute; frequency 1/minute for 4 minutes; effect 1d2 Int damage; cure 2 saves."},{"type":"Startle","kind":"Su","details":"If an undead ningyo attacks in the surprise round, its target must attempt a DC 11 Will save. Success means the target is shaken for 1 round; failure means it is frightened for 1d4 rounds. The target can only be affected by that ningyo's startle once every 24 hours. Creatures with 6 or more Hit Dice are immune to this ability. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Swarming","kind":"Ex","details":"Up to two ningyos can share the same square at the same time. If two ningyos in the same square attack the same foe, they are considered to be flanking that foe as if they were in two opposite squares."}],"description":"The bane of fishermen and divers, ningyos lurk in tropical waters, gorging themselves on fish and attacking anything they can sink their tiny fangs into. Primitive, miniature mer-monsters, ningyos are frightening bogeymen of the sea, often attacking seagoers, ships, and fishing tackle out of blind hunger. These terrors swarm by night and can easily drag opponents down to drown amid a swarm of claws and needling teeth. A slain ningyo always returns to life by night, adopting old habits or searching for its killer, and reverting to a corpse at dawn. Sometimes its corpse washes up on shore as a gruesome and fascinating curiosity, animating the next night to attack its would-be collector. A ningyo measures approximately 2 to 2-1/2 ft. long from head to tail, and weighs 6 to 9 pounds.","ecology":"","habitat_society":""},{"name":"Nixie","cr":1,"xp":400,"alignment":"N","size":"Small","type":"fey","subtypes":["aquatic"],"init":3,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size","hp":9,"hd":"2d6+2","hdvalue":2,"fort":1,"ref":6,"will":4,"dr":"5/cold iron","sr":12,"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"short sword +5 (1d4-2/19-20)","ranged":"light crossbow +5 (1d6/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"water breathing"}]},{"frequency":"3/day","spells":[{"spell":"charm person"}]}],"strength":7,"dexterity":16,"constitution":13,"intelligence":12,"wisdom":13,"charisma":18,"baseatk":1,"cmb":-2,"cmd":11,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":9},{"skill":"Craft (any one)","value":5},{"skill":"Escape Artist","value":8},{"skill":"Handle Animal","value":6},{"skill":"Perception","value":6},{"skill":"Perform (sing)","value":8},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":12},{"skill":"Swim","value":10}],"languages":["Aquan","Sylvan"],"sq":[{"type":"amphibious"},{"type":"wild empathy","details":"+14"}],"environments":["temperate water"],"organizations":["gang (2-4)","band (6-11)","tribe (20-80)"],"treasure":"standard (light crossbow with 20 bolts, short sword)","description_visual":"This green-skinned fey has webbed hands and ft. Its hair is the color of seaweed, and is decorated with shells.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Wild Empathy","kind":"Ex","details":"This ability works like the druid ability of the same name. The nixie's total includes a +8 racial bonus on wild empathy checks."}],"description":"Nixies are guardians of ponds, rivers, lakes, and springs. They prefer dwelling in idyllic places, which they protect from the depredations of predators and careless humanoids. While this often involves confusing enemies and driving foes away, nixies are not afraid of spilling blood to protect their homes-though they prefer not to resort to such means unless completely necessary. Nixies are 4 ft. tall and rarely weigh more than 45 pounds.\n\nNixies avoid combat if possible, using charm person to lead humanoids away from their lairs. They sometimes use this ability\n\nto enslave people to act as protectors or help with a task that is simply too big for them to deal with. They cast water breathing on charmed creatures helping with tasks below the surface. Nixies are reclusive and prefer to keep their presence hidden. They make lairs underwater, forming small communities if their numbers are great enough. Legends speak of a secret nixie kingdom at the bottom of a great lake, but no one has yet confirmed its location.\n\nBOG NIXIES\n\nIn some lands, nixies are evil creatures who lead folk to drown in their waters, either by captivating their targets with song or by assuming the form of an animal or humanoid and tricking a hunter or explorer into dangerous waters. These evil nixies prefer dwelling in festering swamps or blighted fens, and are typically known as bog nixies. The fact that a bog nixie can grant minor wishes, ironically, only increases their opportunities for evil, as brave or foolish explorers deliberately seek them out.\n\nA bog nixie is a neutral evil nixie with the advanced creature template who has the following additional powers. A bog nixie's CR is +2 higher than a normal nixie's.\n\nCaptivating Song (Su): This works like the harpy ability of the same name. The save DC is Charisma-based.\n\nChange Shape (Su): This works as polymorph, and allows the bog nixie to assume the form of any Small or Medium aquatic animal or humanoid.\n\nMinor Wish (Sp): Once per day, a bog nixie can create a magical effect in exchange for a gift or service from a humanoid. The power of this \"wish\" is no greater than what can be done with a 3rd-level spell.","ecology":"","habitat_society":""},{"name":"Octopus","cr":1,"xp":400,"alignment":"N","size":"Small","type":"animal","subtypes":["aquatic"],"init":3,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+3 Dex, +1 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":6,"will":1,"defensive_abilities":["ink cloud"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"speed_mod":"jet 200 ft.","melee":"bite +5 (1d3+1 plus poison), tentacles +3 (grab)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":17,"constitution":14,"intelligence":2,"wisdom":13,"charisma":3,"baseatk":1,"cmb":1,"cmb_special":"+4 vs. grapple","cmd":14,"cmd_special":"can't be tripped","feats":[{"feat":"Multiattack","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Escape Artist","value":13},{"skill":"Stealth","value":20},{"skill":"Swim","value":9}],"environments":["cold oceans","temperate oceans"],"organizations":["solitary"],"treasure":"none","description_visual":"Eight tentacles, each adorned with rows of countless suckers, unfurl from the barrel-shaped body of this large-eyed creature.","source":"PFRPG Bestiary","special_abilities":[{"type":"Ink Cloud","kind":"Ex","details":"An octopus can emit a 10-foot-radius sphere of ink once per minute as a free action. The ink provides total concealment in water, and persists for 1 minute."},{"type":"Jet","kind":"Ex","details":"An octopus can jet backward once per round as a full-round action, at a speed of 200 ft. It must move in a straight line while jetting, and doesn't provoke attacks of opportunity when it does so."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 13; frequency 1/round for 6 rounds; effect 1 Str; cure 1 save."}],"description":"The octopus is a cunning animal capable of using complex tactics to get food.","ecology":"","habitat_society":""},{"name":"Onwu Azu","cr":1,"xp":400,"alignment":"N","size":"Small","type":"animal","subtypes":["aquatic"],"init":3,"senses":[{"type":"keen scent"},{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+3 Dex, +1 size","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":6,"will":0,"defensive_abilities":["ferocity"],"speed":[{"type":"land","speed":5},{"type":"swim","speed":70}],"melee":"bite +3 (1d4+1 plus attach and bleed)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d4"}],"strength":12,"dexterity":16,"constitution":12,"intelligence":1,"wisdom":11,"charisma":3,"baseatk":1,"cmb":1,"cmd":14,"cmd_special":"can't be tripped","feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Swim","value":13}],"sq":[{"type":"glide"}],"environments":["warm oceans","warm rivers"],"organizations":["solitary","school (4-11)","shoal (13-33)"],"treasure":"none","description_visual":"This oversized piranha bursts from the water, spreading broad fins as it takes to the air to sate its hunger.","source":"Plunder & Peril","special_abilities":[{"type":"Attach","kind":"Ex","details":"When an onwu azu hits with a bite attack, it automatically grapples its foe, though the target isn't considered to be grappling the onwu azu. Each round the onwu azu is grappling its foe, it automatically deals its bite damage."},{"type":"Glide","kind":"Ex","details":"An onwu azu can launch itself into the air and glide for up to 1 minute (depending on water and weather conditions, at the GM's discretion). When gliding, it has a fly speed of 60 ft. with clumsy maneuverability and gains Flyby Attack."},{"type":"Keen Scent","kind":"Ex","details":"An onwu azu can notice creatures by scent within a 180-foot radius underwater and can detect blood in the water at ranges of up to 1 mile."}],"description":"Onwu azus are a species of saltwater flying fish that grow to a hefty size and have a taste for the blood of warm-blooded animals. They're similar to giant flying piranha, and their name roughly translates to \"flying death\" in the dialect of Polyglot spoken along the coasts of the western Mwangi Expanse.\n\nLike salmon, onwu azus are born in rivers and migrate downstream to the ocean during their adolescence. There, they grow to their adult size and develop the ability to swim at incredible speeds and use their wing-like pectoral fins to glide above the waves. Onwu azus return to the river where they were born to reproduce, and die shortly afterward.\n\nOnwu azus use their glide ability to hunt prey, and although they are capable of subsisting on smaller fish and other marine animals, they prefer the blood and meat of land-dwelling creatures. After spotting a target, schools of onwu azus soar over the waves at great speeds, hurling themselves at their preferred food sources and biting with their incredibly sharp teeth, employing a suction grip that is difficult to break. Once attached, the onwu azus continue biting until their prey is killed. Their bites cause continuous bleeding, and most of their victims die from shock and blood loss long before the onwu azus reach vital organs. These fish can survive for up to 5 minutes out of the water, and if they succeed at killing their prey on land, they briefly feed before flopping back into the water to look for their next meal.\n\nMore than one pirate has been knocked from his ship by a surprise onwu azu attack. Rather than just leaping to take a bite of air-breathing prey, the fish will often bull rush prey on either a coast or ship's deck, intending to knock it into the waiting mouths of the school below. Shallow inlets and river mouths in the paths of spawning onwu azus are often littered with the remains sailors and explorers who ran afoul of these deadly fish. Adventurers who find treasure in such areas would do well to wonder what killed any corpses lying beside loot and take appropriate precautions.\n\nOnwu azus grow to over 4 ft. in length with fin-spans of over 6 ft., and can weigh close to 90 pounds. Their skin is generally dark blue or brown, and their pectoral fins are a scintillating red that shimmers in the sun with a kaleidoscope of colors.","ecology":"","habitat_society":""},{"name":"Ostrich","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":5,"will":1,"speed":[{"type":"land","speed":60}],"melee":"claw +4 (1d6+4)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":14,"constitution":14,"intelligence":2,"wisdom":13,"charisma":11,"baseatk":1,"cmb":4,"cmd":16,"feats":[{"feat":"Endurance","type":"bonus"},{"feat":"Run","type":"bonus"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":6,"special":"+18 when jumping"},{"skill":"Perception","value":8}],"sq":[{"type":"crouch"}],"environments":["warm deserts","warm plains"],"organizations":["solitary","pair","pride (5-10)","flock (11-50)"],"treasure":"none","description_visual":"This human-sized bird has a long neck and legs sprouting from a round body covered in fluffy gray feathers.","source":"Osirion, Legacy Of Pharaohs","special_abilities":[{"type":"Crouch","kind":"Ex","details":"An ostrich can hide in plain sight as a bush or shrub by crouching down and concealing its head and legs. It makes a Stealth check as normal, but anyone who observes it from within 30 ft. automatically sees through the ruse."}],"description":"Adult female ostriches average 6 ft. tall and weigh about 220 pounds, with males averaging 7 to 9 ft. and 250 pounds. Although they are likely to flee from predators when they can, ostriches are more than willing to stand and fight when trapped or defending their chicks; they're known to kick even lions to death in defense of their young.\n\nA trained ostrich has a market price of 80 gp, whereas an egg is worth 25 gp. Because it's bipedal, an ostrich requires an exotic saddle.\n\nOstrich Companions\n\nAn ostrich can be taken as an animal companion by a druid. An ostrich companion possesses the following base statistics.\n\nStarting Statistics: Size Small; Speed 40 ft.; AC +1 natural armor; Attack claw (1d4); Ability Scores Str 13, Dex 16, Con 12, Int 2, Wis 13, Cha 11; Special Qualities low-light vision.\n\n4th-Level Advancement: Size Medium; Speed 60 ft.; Attack claw (1d6); Ability Scores Str +4, Dex -2, Con +2; Special Qualities crouch.","ecology":"","habitat_society":""},{"name":"Petitioner","cr":1,"xp":400,"race":"Human","alignment":"Any","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":10,"ac_touch":10,"ac_flat_footed":10,"hp":16,"hd":"2d10+5","hdvalue":2,"fort":4,"ref":3,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"slam +2 (1d4)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":10,"constitution":13,"intelligence":10,"wisdom":11,"charisma":10,"baseatk":2,"cmb":2,"cmd":12,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Craft (any two)","value":5},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":5},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":5}],"languages":["Common"],"sq":[{"type":"petitioner traits"}],"environments":["any (Outer Planes)"],"organizations":["solitary","pair","group (3-12)","army (13 or more)"],"treasure":"none","description_visual":"Something seems strange and disturbingly familiar about this wispy, ghostly humanoid shape.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Petitioner Traits","details":"A petitioner has additional abilities and features depending upon its home plane. Its alignment matches the alignment of its home plane."}],"description":"Petitioners are the souls of mortals brought to the Outer Planes after death in order to experience their ultimate punishment, reward, or fate. A petitioner retains fragments of its memories from life, and its appearance depends not only upon the shape it held in life but also upon the nature of the Outer Plane to which it has come. The stat block detailed above presents a typical petitioner formed from the soul of an average human-it doesn't include any of the plane-specific abilities or features a petitioner gains, and should be modified as appropriate depending on the plane to which the petitioner is assigned.\n\nCreatures who die, become petitioners, and then return to life retain no memories of the time they spent as petitioners in the afterlife. A petitioner who dies is gone forever-its \"life force\" has either returned to the Positive Energy Plane or, in some cases, provided the energy to trigger the creation of another outsider. Petitioners who please a deity or another powerful outsider can be granted rewards-the most common such reward manifests as a transformation into a different outsider, such as an archon, azata, demon, or devil, depending upon the petitioner's alignment. In rare cases, a creature can retain its personality from life all the way through its existence as a petitioner and into its third \"life\" as an outsider, although such events are rare indeed.","ecology":"","habitat_society":""}];
